#include <iostream>

int main() {
    int gesamt = 5000;

    int stunden = gesamt / 3600;
    int rest = gesamt % 3600;
    int minuten = rest / 60;
    int sekunden = rest % 60;

    std::cout << gesamt << " Sekunden sind " << stunden << " Stunden, "
              << minuten << " Minuten und " << sekunden << " Sekunden." << std::endl;
    return 0;
}

#include <iostream>

int main() {
    int note1 = 2;
    int note2 = 1;
    int note3 = 2;

    int summe = note1 + note2 + note3;

    double ohne_umwandlung = summe / 3;
    double mit_umwandlung = static_cast<double>(summe) / 3;

    std::cout << "Summe: " << summe << std::endl;
    std::cout << "Ohne Umwandlung: " << ohne_umwandlung << std::endl;
    std::cout << "Mit Umwandlung: " << mit_umwandlung << std::endl;
    return 0;
}
